def longest_uniform_batch(colors, k):
    if k <= 0:
        return 0
    counts = {}
    left = 0
    best = 0
    for right, colour in enumerate(colors):
        counts[colour] = counts.get(colour, 0) + 1
        while len(counts) > k:
            dropped = colors[left]
            counts[dropped] -= 1
            if counts[dropped] == 0:
                del counts[dropped]
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

def pressure_spans(readings):
    spans = []
    stack = []  # indices of readings strictly greater than everything after them
    for i, value in enumerate(readings):
        while stack and readings[stack[-1]] <= value:
            stack.pop()
        spans.append(i + 1 if not stack else i - stack[-1])
        stack.append(i)
    return spans

def min_peak_load(jobs, workers):
    if not jobs:
        return 0
    if workers <= 0:
        return -1

    def fits(cap):
        used = 1
        running = 0
        for cost in jobs:
            if running + cost <= cap:
                running += cost
            else:
                used += 1
                running = cost
                if used > workers:
                    return False
        return True

    lo = max(jobs)
    hi = sum(jobs)
    while lo < hi:
        mid = (lo + hi) // 2
        if fits(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def longest_certifiable_run(checks, k):
    if k < 0:
        return 0
    left = 0
    failures = 0
    best = 0
    for right, check in enumerate(checks):
        failures += check
        while failures > k:
            failures -= checks[left]
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

def largest_wrapped_block(heights):
    stack = []  # bay indices whose heights are strictly increasing
    best = 0
    for i, height in enumerate(list(heights) + [0]):
        while stack and heights[stack[-1]] >= height:
            top = stack.pop()
            left = stack[-1] + 1 if stack else 0
            area = heights[top] * (i - left)
            if area > best:
                best = area
        stack.append(i)
    return best

def slowest_clearing_rate(batches, hours):
    if not batches:
        return 0
    if hours < len(batches):
        return -1

    def clears(rate):
        spent = 0
        for parcels in batches:
            spent += -(-parcels // rate)
            if spent > hours:
                return False
        return True

    lo, hi = 1, max(batches)
    while lo < hi:
        mid = (lo + hi) // 2
        if clears(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
